def check_inclusion(t, s):
    if len(t) > len(s):
        return False
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    window = {}
    satisfied, required = 0, len(need)
    for i, c in enumerate(s):
        window[c] = window.get(c, 0) + 1
        if c in need and window[c] == need[c]:
            satisfied += 1
        if i >= len(t):
            out = s[i - len(t)]
            if out in need and window[out] == need[out]:
                satisfied -= 1
            window[out] -= 1
        if satisfied == required:
            return True
    return False
```

Notice the outgoing-character check happens *before* decrementing its count — you have to compare against the count while it still reflects "was this character exactly satisfying its requirement," then decrement afterward. Getting that order backwards silently miscounts `satisfied`.
